/* ---------- screen: armies ----------
   Home holds two folders: Favorites (the lists starred on this phone) and All lists (every list, with the filters).
   Both show the lists in the order chosen there (newest, A to Z, or by faction), kept on this phone. */
// favorites: list ids starred on this phone (none at first); a list that left the app is not shown
const FAV_KEY = 'wh-favs';
const favIds = () => { const v = store.get(FAV_KEY, []); return Array.isArray(v) ? v.filter(x => typeof x === 'string') : []; };
const isFav = a => favIds().includes(a.id);
const favLists = () => D.armies.filter(isFav);
function setFav(id, on){ const f = favIds().filter(x => x !== id); if(on) f.push(id); store.set(FAV_KEY, f); }
const favBtn = (a, cls) => { const on = isFav(a);
  return '<button class="' + (cls || 'fav') + (on ? ' on' : '') + '" data-fav="' + esc(a.id) + '" aria-pressed="' + on + '" aria-label="Favorite: ' + esc(a.name) + '"><svg aria-hidden="true"><use href="#i-star"/></svg></button>'; };
// each army: its own (silly) name, then tags saying what it is (in a list not grouped by faction, its faction first), then its star
const armyRow = (a, withFaction) => '<div class="arw"><button class="row arow" data-army="' + esc(a.id) + '"><span class="rb"><b>' + esc(a.name) + '<span class="apts">' + esc(a.pointsUsed) + ' pts</span></b>' +
  '<span class="adet"><span>' + (withFaction ? [factionOf(a).name] : []).concat(detachmentsOf(a).map(d => d.name)).map(esc).join(' · ') + '</span></span>' +
  '<span class="adisp tags">' + dispsOf(a).map(x => '<span class="t d' + (x === a.disposition ? ' on' : '') + '">' + esc(x) + (x === a.disposition ? '<span class="vh">, chosen</span>' : '') + '</span>').join('') + '</span></span>' + arrow + '</button>' + favBtn(a) + '</div>';
// the order of a folder: newest (the date New Recruit exported it, or the day it was imported: "exported 17 Oct 2026"; the same day,
// the one added to the app later first), A to Z, or by faction (factions A to Z, each under a band as the Units list's roles, lists A to Z)
const SORTS = [['new', 'Newest first'], ['az', 'A to Z'], ['faction', 'By faction']];
const homeSort = () => { const v = store.get('wh-home-sort'); return SORTS.some(([k]) => k === v) ? v : 'new'; };
const MONTHS = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];
const listDate = a => { const m = /(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})/.exec(a.source || ''); const i = m ? MONTHS.indexOf(m[2].toLowerCase()) : -1;
  return i < 0 ? 0 : Date.UTC(+m[3], i, +m[1]); };
const byName = (x, y) => x.name.localeCompare(y.name, 'en', { sensitivity:'base' });
function armyGroups(list){
  const g = new Map();
  for(const a of list){ const f = factionOf(a).name; if(!g.has(f)) g.set(f, []); g.get(f).push(a); }
  return [...g.keys()].sort((x, y) => x.localeCompare(y)).map(f => '<h2 class="rgh"><span>' + esc(f) + '</span><span class="c">' + g.get(f).length + '</span></h2>' +
    '<div class="list ul">' + g.get(f).sort(byName).map(a => armyRow(a)).join('') + '</div>').join('');
}
function armyList(list){
  const k = homeSort();
  if(k === 'faction') return armyGroups(list);
  const at = new Map(D.armies.map((a, i) => [a, i]));
  const order = list.slice().sort(k === 'az' ? byName : (x, y) => listDate(y) - listDate(x) || at.get(y) - at.get(x));
  return '<div class="list">' + order.map(a => armyRow(a, true)).join('') + '</div>';
}
// home: the two folders, each with how many lists it holds, then the import and how the app is checked
function screenHome(){
  const row = (s, ic, n) => '<button class="row" data-folder="' + s + '"><svg class="ic" aria-hidden="true"><use href="#' + ic + '"/></svg><span class="rb"><b>' + FOLDER_TITLE[s] + '</b></span>' +
    '<span class="c">' + n + '</span>' + arrow + '</button>';
  return '<div class="hlh"><div class="lbl grp-h">Your armies</div></div><div class="list">' + row('favs', 'i-star', favLists().length) + row('lists', 'i-folder', D.armies.length) + '</div>' +
    importRow() + verifiedLine() + (INSTALLED ? '' : '<p class="note">' + installText() + '</p>');
}
// a folder: its order (a button saying which, opening the three), Random, its lists; All lists has the filters too
function screenFolder(s){
  const favs = s === 'favs', all = favs ? favLists() : D.armies, f = favs ? {} : homeFilter(), shown = all.filter(a => hfMatch(a, f));
  if(favs && !all.length) return '<p class="note">No favorites yet. Tap the star next to a list in <button class="link" data-folder="lists">All lists</button> to keep it here as well.</p>';
  const sortLabel = SORTS.find(([k]) => k === homeSort())[1];
  return (!favs && all.length > 2 ? homeFilters(f) : '') +
    '<div class="hlh"><span class="hll">' + (shown.length > 1 ? '<button class="srt" data-sort aria-label="Order: ' + sortLabel + '"><span class="lbl grp-h">' + sortLabel + '</span>' + chev + '</button>' : '') +
    (shown.length < all.length ? '<span class="lbl grp-h hfn">' + shown.length + ' of ' + all.length + '</span>' : '') + '</span>' +
    (shown.length > 1 ? '<button class="rnd" data-roll="' + s + '"><svg class="ic" aria-hidden="true"><use href="#i-dice"/></svg>Random</button>' : '') + '</div>' +
    (shown.length ? '<div class="armies">' + armyList(shown) + '</div>'
      : '<p class="note">No army has all of these. <button class="link" data-hfclear>Clear the filters</button></p>');
}
function showSort(){
  const k = homeSort();
  openSheet('Show lists', 'Order', '<div class="list hfl">' + SORTS.map(([v, label]) => '<button class="row hfo' + (v === k ? ' on' : '') + '" data-sortv="' + v + '" aria-pressed="' + (v === k) + '"><span class="rb"><b>' + label + '</b></span>' +
    (v === k ? '<svg class="ic ok" aria-hidden="true"><use href="#i-check"/></svg>' : '<span class="ic"></span>') + '</button>').join('') + '</div>');
}

const FOLDER_TITLE = { favs:'Favorites', lists:'All lists' };
const isFolder = s => s === 'favs' || s === 'lists';
const calm = c => c.s === 'home' || isFolder(c.s) || c.s === 'army' || c.s === 'settings';   // screens where an update reload loses nothing
  if(isFolder(c.s)) return { s:'home' };
  if(isFolder(c.s)) return FOLDER_TITLE[c.s];
  if(c.s === 'home' || isFolder(c.s)) return true;
  if((cur.s === 'home' || isFolder(cur.s)) && ONLY) cur = Object.assign(plain(cur), { s:'army', army:ONLY.id });
  else if(isFolder(s)) v.innerHTML = screenFolder(s);

  if(el.hasAttribute('data-roll')){ rollArmy(ds.roll); return; }
  if(ds.folder){ go({ s:ds.folder }, isFolder(cur.s) ? 'replace' : undefined); return; }   // (from empty Favorites: All lists in its place, Back still goes home)
  if(el.hasAttribute('data-sort')){ showSort(); return; }
  if(ds.sortv){ store.set('wh-home-sort', ds.sortv); closeSheet(); rerender(); return; }
  if(ds.fav){ const a = armyById(ds.fav); if(!a) return; const on = !isFav(a); setFav(a.id, on);
    if(cur.s === 'army') renderTop(); else { rerender(); const b = document.querySelector('#view [data-fav="' + CSS.escape(a.id) + '"]'); if(b) b.focus({ preventScroll:true }); }
    if(!on && cur.s === 'favs') toastUndo('Removed from Favorites', () => { setFav(a.id, true); rerender(); return null; });
    if(cur.s === 'army' && !ONLY && army()) right = favBtn(army(), 'icon-btn fav');
  if(ds.imprmyes){ if(favIds().includes(ds.imprmyes)) setFav(ds.imprmyes, false); removeImported(ds.imprmyes); return; }   // (its star goes too)
function rollArmy(folder){
  const pool = folder === 'favs' ? favLists() : D.armies.filter(a => hfMatch(a, homeFilter()));

// ---- the home screen's folders ----
// - home-folders: home is two rows, Favorites and All lists, each with its count; a tap opens the folder; Back returns home
// - home-fav: a list's star in All lists adds it to Favorites (kept on this phone, over a reload) and stays in All lists, starred; the star
//   on its Find screen says so and takes it off again; nothing is starred at first; an empty Favorites says how to add one
// - home-sort: each order puts All lists in it (newest: by the date in its source line, A to Z by name, by faction under bands), kept over a
//   reload; the folder screens come back on a reload, with their Back
const homeChecks = async () => {
  // (a tap right after a screen change is dropped; nothing there to tap is a failure, and the checks go on)
  const tap = async q => { await page.waitForTimeout(400); if(!await page.isVisible(q)){ fail('home-tap', '', q, 'nothing visible there to tap'); return; } await page.click(q); await page.waitForTimeout(200); };
  await page.evaluate(() => { localStorage.removeItem('wh-favs'); localStorage.removeItem('wh-home-sort'); hideSheet(); go({ s:'home' }); });
  const h = await page.evaluate(() => [...document.querySelectorAll('#view [data-folder]')].map(b => b.dataset.folder + ':' + b.querySelector('.c').textContent));
  if(h.join() !== 'favs:0,lists:' + armies.length) fail('home-folders', '', 'home', h.join());
  await tap('#view [data-folder="favs"]');
  const e = await page.evaluate(() => ({ s:cur.s, t:$('#top').innerText, rows:document.querySelectorAll('#view .arow').length, hint:/No favorites yet/.test($('#view').innerText), link:!!document.querySelector('#view [data-folder="lists"]') }));
  if(e.s !== 'favs' || !/Favorites/.test(e.t) || e.rows || !e.hint || !e.link) fail('home-fav', '', 'empty Favorites', JSON.stringify(e));
  await tap('#view [data-folder="lists"]');
  const id = armies[armies.length - 1].id;
  await tap(`#view [data-fav="${id}"]`);
  const st = await page.evaluate(id => ({ kept:localStorage.getItem('wh-favs'), on:(document.querySelector(`#view [data-fav="${id}"]`) || { getAttribute:() => 'none' }).getAttribute('aria-pressed'), still:!!document.querySelector(`#view [data-army="${id}"]`) }), id);
  if(st.kept !== JSON.stringify([id]) || st.on !== 'true' || !st.still) fail('home-fav', '', 'star in All lists', JSON.stringify(st));
  await page.reload(); await page.evaluate(() => document.fonts.ready);
  const re = await page.evaluate(() => ({ s:cur.s, back:($('#top [data-back]') || {}).textContent || '' }));
  if(re.s !== 'lists' || re.back !== 'Armies') fail('home-sort', '', 'reload on All lists', JSON.stringify(re));
  await tap('#top [data-back]');
  const hb = await page.evaluate(() => ({ s:cur.s, favs:(document.querySelector('#view [data-folder="favs"] .c') || {}).textContent }));
  if(hb.s !== 'home' || hb.favs !== '1') fail('home-folders', '', 'Back from All lists', JSON.stringify(hb));
  await tap('#view [data-folder="favs"]');
  const fv = await page.evaluate(() => [...document.querySelectorAll('#view .arow')].map(r => r.dataset.army));
  if(fv.join() !== id) fail('home-fav', '', 'Favorites with one', fv.join());
  await tap(`#view [data-army="${id}"]`);
  const fs1 = await page.evaluate(() => { const b = $('#top [data-fav]'); return b ? b.getAttribute('aria-pressed') : 'none'; });
  if(fs1 !== 'true') fail('home-fav', '', 'the star on Find', fs1);
  await tap('#top [data-fav]');
  const fs2 = await page.evaluate(() => ({ on:($('#top [data-fav]') || { getAttribute:() => 'none' }).getAttribute('aria-pressed'), kept:localStorage.getItem('wh-favs') }));
  if(fs2.on !== 'false' || fs2.kept !== '[]') fail('home-fav', '', 'unstarred on Find', JSON.stringify(fs2));
  // - home-fav-undo: unstarred in Favorites, the list leaves it with an Undo; Undo stars it again, with no other toast
  await page.evaluate(id => { store.set('wh-favs', [id]); hideSheet(); go({ s:'home' }); go({ s:'favs' }); }, id);
  await tap(`#view [data-fav="${id}"]`);
  const un = await page.evaluate(() => ({ kept:localStorage.getItem('wh-favs'), toast:$('#toast').innerText, rows:document.querySelectorAll('#view .arow').length }));
  if(un.kept !== '[]' || !/Removed from Favorites/.test(un.toast) || un.rows) fail('home-fav-undo', '', 'unstarred in Favorites', JSON.stringify(un));
  await page.waitForTimeout(400); if(await page.isVisible('#toast [data-undo]')) await page.click('#toast [data-undo]'); else fail('home-fav-undo', '', 'Undo', 'no Undo in the toast');
  await page.waitForTimeout(200);
  const ud = await page.evaluate(() => ({ kept:localStorage.getItem('wh-favs'), toast:$('#toast').classList.contains('show') ? $('#toast').innerText : '', rows:[...document.querySelectorAll('#view .arow')].map(r => r.dataset.army).join() }));
  if(ud.kept !== JSON.stringify([id]) || /Ticks/.test(ud.toast) || ud.rows !== id) fail('home-fav-undo', '', 'Undo', JSON.stringify(ud));
  // - home-fav-stale: a kept star of a list no longer in the app is not counted or shown
  await page.evaluate(id => { store.set('wh-favs', ['gone', id]); hideSheet(); go({ s:'home' }); }, id);
  const sc = await page.evaluate(() => (document.querySelector('#view [data-folder="favs"] .c') || {}).textContent);
  if(sc !== '1') fail('home-fav-stale', '', 'a star of a list that left the app', 'Favorites count ' + sc);
  await page.evaluate(() => { localStorage.removeItem('wh-favs'); hideSheet(); go({ s:'home' }); });
  // the orders
  const dateOf = src => { const m = /(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})/.exec(src || ''); return m ? Date.parse(m[1] + ' ' + m[2] + ' ' + m[3] + ' UTC') : 0; };
  const meta = await page.evaluate(() => WH_DATA.armies.map((a, i) => ({ id:a.id, name:a.name, src:a.source, f:factionOf(a).name, i })));
  const want = {
    new:meta.slice().sort((x, y) => dateOf(y.src) - dateOf(x.src) || y.i - x.i).map(x => x.id),
    az:meta.slice().sort((x, y) => x.name.localeCompare(y.name, 'en', { sensitivity:'base' })).map(x => x.id),
    faction:meta.slice().sort((x, y) => x.f.localeCompare(y.f) || x.name.localeCompare(y.name, 'en', { sensitivity:'base' })).map(x => x.id) };
  if(meta.some(x => !dateOf(x.src))) fail('home-sort', '', 'newest', 'a list without a date in its source line: ' + meta.filter(x => !dateOf(x.src)).map(x => x.id).join(', '));
  await page.evaluate(() => { hideSheet(); go({ s:'lists' }); });
  for(const k of ['az', 'faction', 'new']){
    await tap('#view [data-sort]'); await tap(`#sheetIn [data-sortv="${k}"]`);
    const got = await page.evaluate(() => ({ ids:[...document.querySelectorAll('#view .arow')].map(r => r.dataset.army), bands:document.querySelectorAll('#view .rgh').length, kept:localStorage.getItem('wh-home-sort'), sheet:$('#sheetHost').hidden }));
    if(got.ids.join() !== want[k].join() || got.kept !== JSON.stringify(k) || !got.sheet || (k === 'faction') !== got.bands > 0) fail('home-sort', '', k, JSON.stringify(got));
  }
  await page.evaluate(() => { localStorage.removeItem('wh-favs'); localStorage.removeItem('wh-home-sort'); hideSheet(); go({ s:'home' }); });
};
